book = {}
while True:
    parts = input().split()
    if parts[0] == 'quit':
        break
    if parts[0] == 'add':
        book[parts[1]] = parts[2]
    elif parts[0] == 'find':
        print(book.get(parts[1], parts[1] + ' not found'))
    elif parts[0] == 'delete':
        book.pop(parts[1], None)
